CREATE OR REPLACE FUNCTION public.claim_gateway_recovery_jobs(p_limit integer DEFAULT 25) RETURNS SETOF public.gateway_recovery_queue LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN QUERY WITH picked AS (SELECT q.id FROM public.gateway_recovery_queue q WHERE q.status='pending' AND q.next_retry_at<=now() ORDER BY q.next_retry_at,q.created_at FOR UPDATE SKIP LOCKED LIMIT greatest(1,least(coalesce(p_limit,25),100))) UPDATE public.gateway_recovery_queue q SET status='processing',updated_at=now() FROM picked WHERE q.id=picked.id RETURNING q.*; END; $$; REVOKE ALL ON FUNCTION public.claim_gateway_recovery_jobs(integer) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_gateway_recovery_jobs(integer) TO service_role; CREATE INDEX IF NOT EXISTS idx_gateway_recovery_queue_claim ON public.gateway_recovery_queue(status,next_retry_at,created_at); CREATE UNIQUE INDEX IF NOT EXISTS uq_gateway_recovery_active_attempt ON public.gateway_recovery_queue(user_id,attempt_id) WHERE status IN ('pending','processing');